1	#!/bin/bash
2	fail=0
3	t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\n' > "$t"
4	BOOKINGS=$t bash src/remind.sh 2026-01-02 2>&1 | grep -q '^no bookings: 2026-01-02$' || { echo "a day without bookings"; fail=1; }
5	bash src/remind.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "no date should exit 2"; fail=1; }
